import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Quote: base premiums & processing fee ---
  it("empty item list -> premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result.results[0]).toEqual({ premium: 5 });
  });
  it("single sword -> base 100 + 5 fee = 105 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result.results[0]).toEqual({ premium: 105 });
  });
  it("single amulet -> base 60 + 5 fee = 65 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });
    expect(result.results[0]).toEqual({ premium: 65 });
  });
  it("single staff -> base 80 + 5 fee = 85 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });
    expect(result.results[0]).toEqual({ premium: 85 });
  });
  it("single potion -> base 40 + 5 fee = 45 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });
    expect(result.results[0]).toEqual({ premium: 45 });
  });

  // --- Components & building blocks ---
  it("single rune -> base 25 + 5 fee = 30 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }] }],
    });
    expect(result.results[0]).toEqual({ premium: 30 });
  });
  it.todo("2 runes -> base 50 + 5 fee = 55 G");
  it.todo("3 runes -> block base 60 + 5 fee = 65 G");
  it.todo("4 runes -> base 100 + 5 fee = 105 G (no block)");
  it.todo("7 runes -> base 175 + 5 fee = 180 G (one block of 3 + 4 singles)");
  it.todo("2 runes + 1 moonstone -> base 75 + 5 fee = 80 G (no block, different types)");
  it.todo("3 runes + 3 moonstones -> base 120 + 5 fee = 125 G (two separate blocks)");

  // --- Item-specific modifiers ---
  it.todo("cursed sword (steel, ench 3), newcomer -> 165 G (100 + 50 curse + 10 first + 5 fee)");
  it.todo("sword with enchantment exactly 5 -> high-enchantment surcharge applies");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword + plain amulet -> policy base 160 + 50 curse (of sword) = 210 before modifiers");

  // --- Policy-wide modifiers ---
  it.todo("customer with exactly 2 years -> 20% loyalty discount applies");
  it.todo("first insurance carries 10% initial assessment surcharge");
  it.todo("follow-up contract (after first quote) -> 15% discount");

  // --- Rounding ---
  it.todo("premium yielding 197.5 G -> 198 G (rounded up, in MHPCO's favor)");

  // --- Integration examples ---
  it.todo("newcomer with cursed sword (ench 3) -> 165 G");
  it.todo("long-standing customer (3y) second contract, cursed sword ench 7 -> 160 G");

  // --- Claim: standard reimbursement ---
  it.todo("regular sword (steel, ench 3), damage 500 -> payout 400 (500 - 100 deductible)");
  it.todo("rune (value 250), damage 200 -> payout 100 (200 - 100 deductible)");

  // --- Claim: enchantment threshold ---
  it.todo("dragon sword ench 8, damage 1000 -> payout 400 (50% then deductible)");
  it.todo("dragon sword ench 9, damage 1000 -> payout 400 (both clauses, 50% wins, then deductible)");
  it.todo("dragon sword ench 5, damage 800 -> payout 700 (dragon full, then deductible)");
  it.todo("steel sword ench 9, damage 1000 -> payout 400 (high-ench 50% then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword 500 + amulet 300 -> payout 600 (deductible per item)");

  // --- Claim: payout rounding ---
  it.todo("payout yielding 350.5 G -> 350 G (rounded down, in MHPCO's favor)");

  // --- Claim: cap ---
  it.todo("policy sword + amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword -> cap 2000 (based on unmodified insurance value)");
  it.todo("policy sword + 3 runes block -> insurance sum 1750 (block discount does not affect sum)");
  it.todo("two swords -> insurance sum 2000, cap 4000");
  it.todo("sword cap 2000; two 1500 claims -> first payout 1400 remaining 600, second payout 600 remaining 0");

  // --- Claim: multiple items same type ---
  it.todo("two swords insured, dragon damages both -> each treated separately with own deductible");
  it.todo("more damage entries of a type than insured -> claim rejected (non-zero exit)");

  // --- Edge cases / errors ---
  it.todo("quote with unknown item type -> non-zero exit, error to stderr, no results");
  it.todo("claim referencing item not in policy -> non-zero exit, error to stderr");
  it.todo("claim with negative amount -> non-zero exit, error to stderr");
});

