export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioResult {
  results: unknown[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const sumBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUM[item.type], 0);

const quotePremium = (step: QuoteStep): number =>
  sumBasePremiums(step.items) + PROCESSING_FEE;

const runStep = (step: Step) => ({ premium: quotePremium(step) });

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

