export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface ScenarioResult {
  results: unknown[];
}

const PROCESSING_FEE = 5;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = new Set(["rune", "moonstone"]);

const COMPONENT_PREMIUM = 25;
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

const componentBlockPremium = (count: number): number =>
  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;

const typePremium = (type: string, count: number): number =>
  isComponent(type) ? componentBlockPremium(count) : count * BASE_PREMIUM[type];

const sumTypePremiums = (items: Item[]): number => {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total += typePremium(type, count);
  }
  return total;
};

const quotePremium = (step: QuoteStep): number =>
  sumTypePremiums(step.items) + PROCESSING_FEE;

const runStep = (step: Step) => ({ premium: quotePremium(step) });

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

