});

const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const processClaim = (
  step: ClaimStep,
  policies: Map<number, Policy>,
): { payout: number; remainingCap: number } => {
  const policy = policies.get(step.policy)!;
  const rawPayout = step.incident.damages.reduce(
    (sum, damage) => sum + damagePayout(damage),
    0,
  );
  const payout = Math.min(Math.floor(rawPayout), policy.cap);
  policy.cap -= payout;
